/**
 * src/services/email.js
 *
 * Transactional email service via Brevo (https://app.brevo.com).
 *
 * Required env vars (set in Cloudflare dashboard → Worker → Settings → Variables):
 *   BREVO_API_KEY      — your Brevo API key (v3)
 *   BREVO_FROM_EMAIL   — verified sender address, e.g. hello@consentbit.com
 *   BREVO_FROM_NAME    — sender display name, defaults to "ConsentBit"
 *   WEBAPP_PUBLIC_URL  — production webapp URL, e.g. https://accounts.consentbit.com
 *
 * Three emails are sent automatically:
 *   1. Welcome       — immediately after a new user completes OTP signup
 *   2. Free plan     — after first-setup creates their first site
 *   3. Paid plan     — after Stripe checkout.session.completed is processed
 */

// ---------------------------------------------------------------------------
// Core Brevo HTTP helper
// ---------------------------------------------------------------------------

/**
 * Send a single transactional email via the Brevo v3 API.
 *
 * @param {object} env  Cloudflare Worker env bindings
 * @param {{ to: string, name?: string, subject: string, html: string, text: string }} opts
 */
export async function sendBrevoEmail(env, { to, name, subject, html, text, attachment }) {
  const apiKey   = env.BREVO_API_KEY;
  const fromEmail = env.BREVO_FROM_EMAIL;
  const fromName  = env.BREVO_FROM_NAME || 'ConsentBit';

  if (!apiKey)    { console.warn('[Email] BREVO_API_KEY not set — skipping email'); return; }
  if (!fromEmail) { console.warn('[Email] BREVO_FROM_EMAIL not set — skipping email'); return; }

  const payload = {
    sender:      { email: fromEmail, name: fromName },
    // email.consentbit.com has no MX — route replies to the monitored support inbox.
    replyTo:     { email: env.BREVO_REPLY_TO || 'web@consentbit.com', name: fromName },
    to:          [{ email: to, name: name || to }],
    subject,
    htmlContent: html,
    textContent: text,
  };

  // Optional attachments. Brevo accepts either { url, name } (Brevo fetches the file)
  // or { content: <base64>, name }. We use the url form for the PDF report.
  if (Array.isArray(attachment) && attachment.length) {
    payload.attachment = attachment;
  }

  const res = await fetch('https://api.brevo.com/v3/smtp/email', {
    method:  'POST',
    headers: {
      'content-type': 'application/json',
      'api-key':       apiKey,
      accept:          'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const body = await res.text().catch(() => '');
    console.error('[Email] Brevo send failed', { status: res.status, to, subject, snippet: body.slice(0, 300) });
  } else {
  }
}

// ---------------------------------------------------------------------------
// Temporary per-customer mute (billing / plan / scan-limit emails only)
// ---------------------------------------------------------------------------

// Recipients that must not get billing, plan or scan-limit emails. Entries are
// full addresses or "@domain" for a whole company. Login codes, verify links and
// team emails are NOT muted — those don't check this list.
// Platan Hotels (2026-10-03): 15 sites moved to manual Stripe subscriptions —
// remove the entry when they want emails again.
const MUTED_EMAIL_RECIPIENTS = [
  '@platanhotels.pl',
];

function isEmailMuted(to) {
  const addr = String(to || '').trim().toLowerCase();
  if (!addr) return false;
  return MUTED_EMAIL_RECIPIENTS.some(m => (m.startsWith('@') ? addr.endsWith(m) : addr === m));
}

function skipMuted(kind, to) {
  if (!isEmailMuted(to)) return false;
  console.log(`[Email] ${kind} skipped — recipient is muted`, { to });
  return true;
}

