// handlers/consentLogs.js
import { ensureSchema } from '../services/db.js';
import { capturePostHogEvent } from '../services/posthog.js';
import { truncateIp } from '../utils/ipTruncate.js';
import { consentViewCutoff } from '../services/consentRetention.js';
import { resolveEffectivePlanId } from './bannerCustomization.js';

export async function handleConsentLogs(request, env) {
  const db = env.CONSENT_WEBAPP;

  if (request.method !== 'GET') {
    return Response.json({ success: false, error: 'Method Not Allowed' }, { status: 405 });
  }

  const url = new URL(request.url);
  const siteId = url.searchParams.get('siteId');
  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || '100', 10), 1), 500);
  const offset = Math.max(parseInt(url.searchParams.get('offset') || '0', 10), 0);
  const year = url.searchParams.get('year');   // e.g. "2025"
  const month = url.searchParams.get('month'); // e.g. "04"
  // Lookup by ID, TEST-ONLY (LAW_FIXES="1"). Matches either the visitor consent ID
  // (Consent.deviceId → every record that visitor made on this site, for their access /
  // deletion request) or a record ID (Consent.id → that one choice, for old records).
  const visitorId = env.LAW_FIXES === '1' ? String(url.searchParams.get('deviceId') || '').trim().slice(0, 128) : '';


  if (!siteId) {
    return Response.json({ success: false, error: 'siteId is required' }, { status: 400 });
  }

  try {
    await ensureSchema(db);

    // consent_logs_viewed (action: view) — fire on the first page only (offset 0) so
    // pagination doesn't double-count, and only for Webflow sites.
    if (offset === 0) {
      try {
        const ownerRow = await db.prepare(
          `SELECT u.email AS email, s.platform AS platform FROM Site s
             JOIN OrganizationMember om ON om.organizationId = s.organizationId
             JOIN User u ON u.id = om.userId WHERE s.id = ?1 LIMIT 1`
        ).bind(siteId).first();
        if (ownerRow?.email && String(ownerRow.platform || '').toLowerCase() === 'webflow') {
          await capturePostHogEvent(env, ownerRow.email, 'consent_logs_viewed', {
            action: 'view',
            platform: 'webflow',
            site_id: siteId,
          });
        }
      } catch { /* analytics only */ }
    }

    // Free plan: only the last 3 months are visible (TEST-ONLY via LAW_FIXES). null = no limit.
    const viewCutoff = await consentViewCutoff(env, siteId, resolveEffectivePlanId);

    const hasDateFilter = year && month;
    const paddedMonth = hasDateFilter ? month.padStart(2, '0') : '';

    const { results: consents } = visitorId
      ? await db
          .prepare(
            `SELECT id, siteId, deviceId, ipAddress, userAgent, country, region, is_eu,
                    createdAt, updatedAt, regulation, bannerType, consentMethod, status, expiresAt, consent_categories, domain
             FROM Consent WHERE siteId = ?1 AND (deviceId = ?4 OR id = ?4) AND (?5 IS NULL OR createdAt >= ?5)
             ORDER BY createdAt DESC LIMIT ?2 OFFSET ?3`
          )
          .bind(siteId, limit, offset, visitorId, viewCutoff)
          .all()
      : hasDateFilter
      ? await db
          .prepare(
            `SELECT id, siteId, deviceId, ipAddress, userAgent, country, region, is_eu,
                    createdAt, updatedAt, regulation, bannerType, consentMethod, status, expiresAt, consent_categories, domain
             FROM Consent WHERE siteId = ?1
               AND strftime('%Y', createdAt) = ?4
               AND strftime('%m', createdAt) = ?5 AND (?6 IS NULL OR createdAt >= ?6)
             ORDER BY createdAt DESC LIMIT ?2 OFFSET ?3`
          )
          .bind(siteId, limit, offset, year, paddedMonth, viewCutoff)
          .all()
      : await db
          .prepare(
            `SELECT id, siteId, deviceId, ipAddress, userAgent, country, region, is_eu,
                    createdAt, updatedAt, regulation, bannerType, consentMethod, status, expiresAt, consent_categories, domain
             FROM Consent WHERE siteId = ?1 AND (?4 IS NULL OR createdAt >= ?4) ORDER BY createdAt DESC LIMIT ?2 OFFSET ?3`
          )
          .bind(siteId, limit, offset, viewCutoff)
          .all();

    const totalStmt = visitorId
      ? await db
          .prepare('SELECT COUNT(*) as total FROM Consent WHERE siteId = ?1 AND (deviceId = ?2 OR id = ?2) AND (?3 IS NULL OR createdAt >= ?3)')
          .bind(siteId, visitorId, viewCutoff)
          .first()
      : hasDateFilter
      ? await db
          .prepare(
            `SELECT COUNT(*) as total FROM Consent WHERE siteId = ?1
               AND strftime('%Y', createdAt) = ?2
               AND strftime('%m', createdAt) = ?3 AND (?4 IS NULL OR createdAt >= ?4)`
          )
          .bind(siteId, year, paddedMonth, viewCutoff)
          .first()
      : await db
          .prepare('SELECT COUNT(*) as total FROM Consent WHERE siteId = ?1 AND (?2 IS NULL OR createdAt >= ?2)')
          .bind(siteId, viewCutoff)
          .first();

    const total = totalStmt?.total ?? 0;

    const logs = (consents || []).map((row) => {
      let categories = null;
      // Cross-domain consent: host the choice was copied from (consentMethod "shared"). Kept as
      // its own field because `categories` below is narrowed to the inner category flags.
      let sharedFrom = null;
      if (row.consent_categories) {
        try {
          const parsed = typeof row.consent_categories === 'string' ? JSON.parse(row.consent_categories) : row.consent_categories;
          categories = parsed && typeof parsed.categories === 'object' ? parsed.categories : parsed;
          if (parsed && typeof parsed.sharedFrom === 'string') sharedFrom = parsed.sharedFrom.slice(0, 253);
        } catch (_) {
          categories = null;
        }
      }
      return {
        id: row.id,
        siteId: row.siteId,
        deviceId: row.deviceId,
        ipAddress: truncateIp(row.ipAddress),
        userAgent: row.userAgent,
        country: row.country,
        region: row.region,
        is_eu: row.is_eu,
        createdAt: row.createdAt,
        updatedAt: row.updatedAt,
        regulation: row.regulation,
        bannerType: row.bannerType,
        consentMethod: row.consentMethod,
        status: row.status,
        expiresAt: row.expiresAt,
        domain: row.domain,
        categories,
        sharedFrom,
      };
    });


    // One row per (siteId, name, domain) — latest by lastSeenAt (no duplicates in inventory)
    const { results: cookieRows } = await db
      .prepare(
        `SELECT id, name, domain, path, category, provider, description, expires, source, lastSeenAt FROM (
          SELECT *, ROW_NUMBER() OVER (PARTITION BY siteId, name, COALESCE(domain, '') ORDER BY lastSeenAt DESC) as rn
          FROM Cookie
          WHERE siteId = ?1 AND (isExpected = 0 OR isExpected IS NULL) AND name NOT LIKE 'consentbit%'
        ) WHERE rn = 1
        ORDER BY category, provider, name`
      )
      .bind(siteId)
      .all();

    const cookies = (cookieRows || []).map((row) => {
      const { rn, RN, ...rest } = row;
      return rest;
    });

    // Published user-defined cookie rules for this site
    let customCookieRules = [];
    try {
      const { results: ccrRows } = await db
        .prepare(
          `SELECT id, name, domain, scriptUrlPattern, category, duration, description
           FROM CustomCookieRule
           WHERE siteId = ?1 AND published = 1
           ORDER BY category, name`
        )
        .bind(siteId)
        .all();
      customCookieRules = ccrRows || [];
    } catch (_) {
      // Non-fatal — omit custom rules if the table doesn't exist yet
    }

    return Response.json({
      success: true,
      consents: logs,
      cookies,
      customCookieRules,
      total,
      limit,
      offset,
      // Records older than this date are hidden (Free plan, 3 months). null = no limit.
      viewCutoff,
    });
  } catch (error) {
    console.error('[ConsentLogs] Error:', error);
    return Response.json(
      { success: false, error: error?.message || 'Failed to fetch consent logs' },
      { status: 500 }
    );
  }
}
